from rules import choices


def _active_dependencies(row, features):
    for dep in row.get("deps", []):
        feature = dep.get("feature")
        if feature and feature not in features:
            continue
        yield dep


def _is_acyclic(assigned, features):
    graph = {
        name: [dep["name"] for dep in _active_dependencies(row, features)]
        for name, row in assigned.items()
    }
    states = {}

    def visit(name):
        state = states.get(name, 0)
        if state == 1:
            return False
        if state == 2:
            return True
        states[name] = 1
        for child in graph.get(name, []):
            if not visit(child):
                return False
        states[name] = 2
        return True

    return all(visit(name) for name in graph)


def solve(data):
    packages = data["packages"]
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []))
    names = sorted(packages)

    constraints = {name: [interval] for name, interval in roots.items()}
    if any(name not in packages for name in constraints):
        return {"error": "unsatisfiable"}

    best_versions = None
    best_score = None

    def search(assigned, required):
        nonlocal best_versions, best_score

        pending = [name for name in required if name not in assigned]
        if not pending:
            if not _is_acyclic(assigned, features):
                return
            versions = {name: row["version"] for name, row in assigned.items()}
            score = tuple(versions.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = versions
            return

        name = min(pending)
        for row in choices(
            packages.get(name, []),
            required[name],
            blocked.get(name, []),
            pins.get(name),
        ):
            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_required = {key: list(value) for key, value in required.items()}

            valid = True
            for dep in _active_dependencies(row, features):
                dep_name = dep["name"]
                interval = (dep["min"], dep["max"])
                next_required.setdefault(dep_name, []).append(interval)
                if dep_name in next_assigned:
                    version = next_assigned[dep_name]["version"]
                    if not all(low <= version <= high
                               for low, high in next_required[dep_name]):
                        valid = False
                        break
            if valid:
                search(next_assigned, next_required)

    search({}, constraints)
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

def choices(rows, intervals=None, blocked=None, pin=None):
    if intervals is None:
        intervals = []
    if blocked is None:
        blocked = []
    return sorted(
        (row for row in rows
         if all(low <= row["version"] <= high for low, high in intervals)
         and row["version"] not in blocked
         and (pin is None or row["version"] == pin)),
        key=lambda row: row["version"],
        reverse=True,
    )
